fun main() {
    val words = listOf("apple", "avocado", "banana", "blueberry", "cherry", "apricot")
    println(words.groupBy { it[0] })
    println(words.groupBy({ it.length }, { it.uppercase() }))
    println(words.associateWith { it.length })
    println(words.associateBy { it.first() })
    println(words.associate { it to it.last() })
    println(words.partition { it.length > 6 })
    println((1..10).chunked(3))
    println((1..6).windowed(3))
    println((1..7).windowed(3, 2, true))
    println(listOf(1, 2, 3).zip(listOf("a", "b")))
    println(listOf(1, 2, 3).zip(listOf("a", "b", "c")) { n, s -> "$s$n" })
    println(listOf(1, 2, 3).fold(10) { acc, x -> acc + x })
    println(listOf(1, 2, 3).foldRight("") { x, acc -> acc + x })
    println(listOf(1, 2, 3, 4).scan(0) { a, b -> a + b })
    println(listOf(1, 2, 3, 4).runningReduce { a, b -> a * b })
    println(listOf(1, 2, 3).reduce { a, b -> a - b })
    println(words.groupingBy { it.length }.eachCount())
    println(listOf(Pair(1, "a"), Pair(2, "b")).unzip())
    println(listOf(1, 2, 3, 4).zipWithNext())
    println(words.flatMap { it.take(2).toList() }.distinct())
    println(listOf(listOf(1), listOf(2, 3)).flatten())
    println(words.count { 'e' in it })
    println(words.any { it.startsWith("c") } to words.all { it.length > 4 })
    println(words.take(2) + words.takeLast(1) - "apple")
    println(words.slice(1..2))
    println(words.indexOfFirst { it.startsWith("b") })
}
